// Package protos gives the base domain and cmd/rsgen the run-time error tables
// of TiDB: the util/dbterror prototypes by name (protos_list.go, generated by
// `go run ./cmd/rsgen -protos`) and the error registry of the tidb-server
// package set.
package protos

import (
	"sort"

	"github.com/pingcap/tidb/pkg/parser/terror"

	// The package set of cmd/tidb-server (its imports), so that every error
	// class/code registered at init is in terror.ErrClassToMySQLCodes, as in
	// tidb-server after terror.RegisterFinish.
	_ "github.com/pingcap/tidb/pkg/bindinfo"
	_ "github.com/pingcap/tidb/pkg/ddl"
	_ "github.com/pingcap/tidb/pkg/domain"
	_ "github.com/pingcap/tidb/pkg/executor"
	_ "github.com/pingcap/tidb/pkg/extension/_import"
	_ "github.com/pingcap/tidb/pkg/planner/core"
	_ "github.com/pingcap/tidb/pkg/plugin"
	_ "github.com/pingcap/tidb/pkg/privilege/privileges"
	_ "github.com/pingcap/tidb/pkg/server"
	_ "github.com/pingcap/tidb/pkg/session"
	_ "github.com/pingcap/tidb/pkg/statistics"
	_ "github.com/pingcap/tidb/pkg/store"
	_ "github.com/pingcap/tidb/pkg/store/copr"
	_ "github.com/pingcap/tidb/pkg/store/driver"
	_ "github.com/pingcap/tidb/pkg/store/mockstore"
)

// RegistrySnapshot is terror.ErrClassToMySQLCodes as sorted (class, codes).
func RegistrySnapshot() [][2]any {
	var cls []int
	for c := range terror.ErrClassToMySQLCodes {
		cls = append(cls, int(c))
	}
	sort.Ints(cls)
	var out [][2]any
	for _, c := range cls {
		var codes []int
		for code := range terror.ErrClassToMySQLCodes[terror.ErrClass(c)] {
			codes = append(codes, int(code))
		}
		sort.Ints(codes)
		out = append(out, [2]any{c, codes})
	}
	return out
}
